import type { ActionContext } from '../../data/action_context'
import type { ActionDefinition } from '../../data/action_types'

const FOLDER_PLACEHOLDER_NAMES = 'worktree-folder|repository-folder|project-folder|releases-folder'
const CARD_PLACEHOLDER_NAMES = 'card-file|card-title|card-prompt'
const PLACEHOLDER_PATTERN = new RegExp(`\\{\\{\\s*(${FOLDER_PLACEHOLDER_NAMES}|${CARD_PLACEHOLDER_NAMES})\\s*\\}\\}`, 'gu')
const CARD_PROMPT_PLACEHOLDER_PATTERN = /\{\{\s*card-prompt\s*\}\}/u

export interface ActionFolderPlaceholderValues {
    projectFolder: string
    repositoryFolder: string
    releasesFolder: string
    worktreeFolder: string
}

export function resolvePlaceholders(
    text: string,
    context: ActionContext,
    folders: ActionFolderPlaceholderValues,
    extraPrompt: string,
): string {
    return text.replace(PLACEHOLDER_PATTERN, (_match, name: string) => {
        if (name === 'worktree-folder') {
            if (!folders.worktreeFolder) throw new Error('Cannot resolve worktree-folder without a run checkout path')

            return folders.worktreeFolder
        }
        if (name === 'repository-folder') {
            if (!folders.repositoryFolder) throw new Error('Cannot resolve repository-folder without an opened repository path')

            return folders.repositoryFolder
        }
        if (name === 'project-folder') {
            if (!folders.projectFolder) throw new Error('Cannot resolve project-folder without a configured project path')

            return folders.projectFolder
        }
        if (name === 'releases-folder') {
            if (!folders.releasesFolder) throw new Error('Cannot resolve releases-folder without a configured releases folder')

            return folders.releasesFolder
        }

        if (name === 'card-prompt') return extraPrompt

        if (name === 'card-title') {
            if (!context.title) throw new Error('Cannot resolve card-title placeholder without a card title')

            return context.title
        }

        if (!context.file) throw new Error('Cannot resolve card-file placeholder without a file context')

        return context.file
    })
}

export function resolveAgentPrompt(
    action: ActionDefinition,
    context: ActionContext,
    folders: ActionFolderPlaceholderValues,
    extraPrompt: string,
): string {
    if (!action.prompt) throw new Error(`Missing prompt for agent action "${action.label}"`)
    const resolvedText = resolvePlaceholders(action.prompt, context, folders, extraPrompt)
    if (CARD_PROMPT_PLACEHOLDER_PATTERN.test(action.prompt)) return resolvedText
    if (extraPrompt.trim().length === 0) return resolvedText

    return `${resolvedText}\n\n${extraPrompt}`
}

import type { ActionContext } from './action_context'
import type { AgentConversation, AgentConversationEventEntry, AgentConversationMessageEntry } from './data_types'
import type { ThinkingLevel } from './agent_profiles'
import type { ActionAutoFinish, ActionType } from './action_types'

export type ActionRunTerminalStatus = 'cancelled' | 'completed' | 'failed' | 'okButNotAfter'
export type ActionRunStatus = ActionRunTerminalStatus | 'queued' | 'running' | 'waitingForInput'
export type ActionRunPhase = 'after' | 'before' | 'main' | 'on'

export interface ActionRunInput {
    accessLevel?: string
    agent?: string
    approvalPolicy?: string
    continueFrom?: string
    extraPrompt?: string
    model?: string
    prompt?: string
    thinkingLevel?: ThinkingLevel
}

export interface ActionPromptRequest {
    actionId: string
    context: ActionContext
}

export interface PreparedActionPrompt {
    prompt: string
}

export interface AgentConversationReservation {
    conversationId: string
    reference: string
}

export interface ActionStartRequest {
    actionId: string
    conversationReservation?: AgentConversationReservation
    context: ActionContext
    runInput: ActionRunInput
}

export interface AgentQuestionOption {
    description?: string
    label: string
}

export interface AgentQuestion {
    header: string
    id: string
    isOther?: boolean
    isSecret?: boolean
    options?: AgentQuestionOption[] | null
    question: string
}

export type AgentApprovalRequestId = number | string
export type AgentNetworkProtocol = 'http' | 'https' | 'socks5Tcp' | 'socks5Udp'
export type AgentFileSystemPath =
    | { path: string, type: 'path' }
    | { pattern: string, type: 'glob_pattern' }
    | { type: 'special', value: string }
export interface AgentAdditionalPermissions {
    fileSystem: {
        entries?: { access: 'deny' | 'read' | 'write', path: AgentFileSystemPath }[]
        read: string[] | null
        write: string[] | null
    } | null
    network: { enabled: boolean | null } | null
}
export type AgentCommandAction =
    | { command: string, name: string, path: string, type: 'read' }
    | { command: string, path: string | null, type: 'listFiles' }
    | { command: string, path: string | null, query: string | null, type: 'search' }
    | { command: string, type: 'unknown' }
export interface AgentNetworkPolicyAmendment {
    action: 'allow' | 'deny'
    host: string
}
export type AgentApprovalDecision =
    | 'accept'
    | 'acceptForSession'
    | 'cancel'
    | 'decline'
    | { acceptWithExecpolicyAmendment: { execpolicy_amendment: string[] } }
    | { applyNetworkPolicyAmendment: { network_policy_amendment: AgentNetworkPolicyAmendment } }
export interface AgentApproval {
    additionalPermissions?: AgentAdditionalPermissions | null
    approvalId?: string | null
    availableDecisions?: AgentApprovalDecision[] | null
    command?: string | null
    commandActions?: AgentCommandAction[] | null
    cwd?: string | null
    environmentId?: string | null
    filePaths: string[]
    grantRoot?: string | null
    input?: Record<string, unknown> | null
    itemId: string
    kind: 'commandExecution' | 'fileChange' | 'toolUse'
    networkApprovalContext?: { host: string, protocol: AgentNetworkProtocol } | null
    proposedExecpolicyAmendment?: string[] | null
    proposedNetworkPolicyAmendments?: AgentNetworkPolicyAmendment[] | null
    provider?: 'claude' | 'codex'
    permissionSuggestions?: unknown[] | null
    reason?: string | null
    requestId: AgentApprovalRequestId
    startedAtMs: number
    threadId?: string
    toolName?: string | null
    turnId?: string
}

interface ActionRunEventBase {
    actionId: string
    actionType?: ActionType
    autoFinish?: ActionAutoFinish | null
    context: ActionContext
    runId: string
    interactionReady?: boolean
    phase: ActionRunPhase
    rootActionId: string
    sequence?: number
    streaming?: boolean
}

export type ActionRunUpdate =
    | {
        continued?: boolean
        conversation: AgentConversation
        kind: 'agentStarted'
    }
    | {
        conversation: AgentConversation
        kind: 'agentClosed'
    }
    | {
        kind: 'agentQuestion'
        questions: AgentQuestion[]
        requestId: number | string | null
    }
    | {
        approval: AgentApproval
        kind: 'agentApproval'
    }
    | {
        kind: 'agentApprovalResolved' | 'agentApprovalSubmitted'
        requestId: AgentApprovalRequestId
    }
    | {
        kind: 'agentQuestionAnswer' | 'agentUserMessage'
        userMessage: AgentConversationMessageEntry
    }
    | {
        event: AgentConversationEventEntry
        kind: 'agentEvent'
    }
    | {
        command?: string
        content: string
        kind: 'error' | 'output'
        messageId?: string
        previousContent?: string
        replace?: boolean
        sequence?: number
    }

export type ActionRunEvent =
    | ActionRunEventBase & {
        status: ActionRunStatus
        type: 'run'
    }
    | ActionRunEventBase & {
        command?: string
        conversationId?: string
        runWorktree?: number | null
        message?: string | null
        accessLevel?: string
        approvalPolicy?: string
        reference?: string
        status: ActionRunStatus
        thinkingLevel?: ThinkingLevel
        type: 'action'
    }
    | ActionRunEventBase & {
        status: 'running' | 'waitingForInput'
        type: 'agentState'
    }
    | ActionRunEventBase & {
        status: ActionRunStatus
        type: 'update'
        update: ActionRunUpdate
    }

export interface ActionRunLogEntry {
    accessLevel?: string
    actionId: string
    actionName: string
    approvalPolicy?: string
    command: string | null
    message: string
    phase: ActionRunPhase
    status: ActionRunStatus
    stderr: string
    stdout: string
    thinkingLevel?: ThinkingLevel
}

export interface ActionRunResult {
    logs: ActionRunLogEntry[]
    status: ActionRunStatus
}

